"use client";

import { useCart } from "@/context/CartContext";
import { ShoppingCart } from "lucide-react";
import Link from "next/link";


type BookProps = {
  id: number;
  title: string;
  author: string;
  image: string;
  available: boolean;
};


export default function BookCard({
  id,
  title,
  author,
  image,
  available,
}: BookProps) {

  const { addToCart } = useCart();


  return (
    <div className="rounded-xl border bg-white p-4 shadow">

      <Link href={`/books/${id}`}>

        <img
          src={image}
          alt={title}
          className="h-64 w-full cursor-pointer rounded-lg object-cover"
        />

      </Link>


      <Link href={`/books/${id}`}>

        <h2 className="mt-3 cursor-pointer text-xl font-bold hover:underline">
          {title}
        </h2>

      </Link>


      <p className="text-gray-600">
        {author}
      </p>


      <button
        onClick={() =>
          addToCart({
            id,
            title,
            author,
            image,
          })
        }
        className="mt-4 flex w-full items-center justify-center gap-2 rounded-lg bg-black px-4 py-2 text-white"
      >

        <ShoppingCart size={18}/>

        Borrow Book

      </button>

    </div>
  );
}